on-arrival: {!

// --- Electorate modifiers (rebuilt before every poll in Q.update_projections) -------
// Events/cards set Q flags; modifiers here read those flags and shift competitive layers.
// Scopes: stratum (demographic), district (region), global.

var ELECTORATE_PARTY_KEYS = ['D', 'I', 'C', 'G', 'H']

function electorateZeroScores() {
    return { D: 0, I: 0, C: 0, G: 0, H: 0 }
}

function electorateCopyScores(src) {
    var out = electorateZeroScores()
    for (var i = 0; i < ELECTORATE_PARTY_KEYS.length; i++) {
        var k = ELECTORATE_PARTY_KEYS[i]
        out[k] = (src && src[k]) || 0
    }
    return out
}

function electorateAddDelta(scores, party, delta) {
    if (scores && scores[party] !== undefined) {
        scores[party] += delta
    }
}

class ElectorateModifier {
    /**
     * @param {object} opts
     * @param {string} opts.id - unique name for debugging
     * @param {'stratum'|'district'|'global'} opts.scope
     * @param {string} [opts.target] - stratum id (e.g. alien) or district id (e.g. Aurora)
     * @param {'D'|'I'|'C'|'G'|'H'} opts.party
     * @param {number} opts.delta - additive competitive logit shift
     * @param {function(Q): boolean} [opts.activeIf] - defaults to always on
     */
    constructor(opts) {
        this.id = opts.id
        this.scope = opts.scope
        this.target = opts.target
        this.party = opts.party
        this.delta = opts.delta || 0
        this.activeIf = opts.activeIf || function() { return true }
    }

    isActive(q) {
        try {
            return !!this.activeIf(q)
        } catch (e) {
            return false
        }
    }

    apply(state, q) {
        if (!this.isActive(q)) { return }
        if (this.scope === 'stratum') {
            var dem = state.demographicsById[this.target]
            if (dem) { electorateAddDelta(dem.competitiveScores, this.party, this.delta) }
        } else if (this.scope === 'district') {
            var dist = state.districtsById[this.target]
            if (dist) { electorateAddDelta(dist.competitiveScores, this.party, this.delta) }
        } else if (this.scope === 'global') {
            electorateAddDelta(state.global.competitiveScores, this.party, this.delta)
        }
    }
}

Q.ElectorateModifier = ElectorateModifier

/** All competitive shifts from story state; edit this list as events/cards gain flags. */
Q.electorateModifierCatalog = [
    // Example: after February 2300, otherworlder stratum leans slightly Dem (convention / migration season).
    new ElectorateModifier({
        id: 'example_alien_dems_after_february_2300',
        scope: 'stratum',
        target: 'alien',
        party: 'D',
        delta: 0.2,
        activeIf: function(q) {
            return q.year > 2300 || (q.year === 2300 && q.month >= 2)
        },
    }),
]

Q.applyElectorateModifiers = function() {
    var state = Q.electionV2
    if (!state) { return }

    state.demographicsById = state.demographicsById || Object.fromEntries(
        state.demographics.map(function(d) { return [d.id, d] })
    )
    state.districtsById = state.districtsById || Object.fromEntries(
        state.districts.map(function(d) { return [d.id, d] })
    )

    for (var i = 0; i < state.demographics.length; i++) {
        var dem = state.demographics[i]
        dem.competitiveScores = electorateCopyScores(
            dem._baseCompetitiveScores || dem.competitiveScores
        )
    }
    for (var j = 0; j < state.districts.length; j++) {
        var dist = state.districts[j]
        dist.competitiveScores = electorateCopyScores(
            dist._baseCompetitiveScores || dist.competitiveScores
        )
    }
    state.global.competitiveScores = electorateCopyScores(
        state._baseGlobalScores || state.global.competitiveScores
    )

    for (var m = 0; m < Q.electorateModifierCatalog.length; m++) {
        Q.electorateModifierCatalog[m].apply(state, Q)
    }
}

Q.update_projections();

Q.has_event = 0;
// check if there are any cards in #event, and then go to main if not.
var scene = this.game.scenes['post_event.events_choice'];
var choices = this._compileChoices(scene);
if (choices && choices[0].title != "Continue...") {
    Q.has_event = 1;
} else {
    has_event = 0;
}
// pre-load all of the event images
if (this.ui && this.ui.show_portraits) {
    for (var choice of choices) {
        var cc = this.game.scenes[choice.id];
        if (cc.faceImage) {
            var im = new Image();
            im.url = cc.faceImage;
        }
    }
}

if (typeof window !== "undefined" && window.generateBar) {
}
