input.old_string:
class ElectorateModifier {
    /**
     * Positional (table-friendly):
     *   new ElectorateModifier(id, scope, target, party, delta [, activeIf])
     * scope: 'stratum' | 'district' | 'global' — use '' for target when global.
     * party: 'D' | 'I' | 'C' | 'G' | 'H'
     * Object form still works: new ElectorateModifier({ id, scope, ... })
     */
    constructor(id, scope, target, party, delta, activeIf) {
        if (id && typeof id === 'object') {
            var opts = id
            id = opts.id
            scope = opts.scope
            target = opts.target
            party = opts.party
            delta = opts.delta
            activeIf = opts.activeIf
        }
        this.id = id
        this.scope = scope
        this.target = target || ''
        this.party = party
        this.delta = delta || 0
        this.activeIf = activeIf || function() { return true }
    }

    isActive(q) {
        try {
            return !!this.activeIf(q)
        } catch (e) {
            return false
        }
    }

    apply(state, q) {
        if (!this.isActive(q)) { return }
        if (this.scope === 'stratum') {
            var dem = state.demographicsById[this.target]
            if (dem) { electorateAddDelta(dem.competitiveScores, this.party, this.delta) }
        } else if (this.scope === 'district') {
            var dist = state.districtsById[this.target]
            if (dist) { electorateAddDelta(dist.competitiveScores, this.party, this.delta) }
        } else if (this.scope === 'global') {
            electorateAddDelta(state.global.competitiveScores, this.party, this.delta)
        }
    }
}

input.new_string:
class ElectorateModifier {
    /**
     * Positional (table-friendly):
     *   new ElectorateModifier(id, scope, target, party, delta [, activeIf])
     * id: also the Q quality name; strength = Q[id] (stack count).
     * scope: 'stratum' | 'district' | 'global' — use '' for target when global.
     * party: 'D' | 'I' | 'C' | 'G' | 'H'
     * activeIf: optional extra gate; stacks still come from Q[id].
     */
    constructor(id, scope, target, party, delta, activeIf) {
        var fromObject = id && typeof id === 'object'
        if (fromObject) {
            var opts = id
            id = opts.id
            scope = opts.scope
            target = opts.target
            party = opts.party
            delta = opts.delta
            activeIf = opts.activeIf
        }
        this.id = id
        this.scope = scope
        this.target = target || ''
        this.party = party
        this.delta = delta || 0
        this.gateWithActiveIf = fromObject
            ? activeIf != null
            : arguments.length >= 6 && activeIf != null
        this.activeIf = activeIf || function() { return true }
    }

    /** Stack count from Q[modifier id]; non-numeric or <= 0 → no effect. */
    stacksFromQ(q) {
        if (!q || q[this.id] == null) { return 0 }
        var n = Number(q[this.id])
        if (isNaN(n) || n <= 0) { return 0 }
        return n
    }

    isActive(q) {
        try {
            return !!this.activeIf(q)
        } catch (e) {
            return false
        }
    }

    apply(state, q) {
        var stacks = this.stacksFromQ(q)
        if (stacks <= 0) { return }
        if (this.gateWithActiveIf && !this.isActive(q)) { return }
        var shift = this.delta * stacks
        if (this.scope === 'stratum') {
            var dem = state.demographicsById[this.target]
            if (dem) { electorateAddDelta(dem.competitiveScores, this.party, shift) }
        } else if (this.scope === 'district') {
            var dist = state.districtsById[this.target]
            if (dist) { electorateAddDelta(dist.competitiveScores, this.party, shift) }
        } else if (this.scope === 'global') {
            electorateAddDelta(state.global.competitiveScores, this.party, shift)
        }
    }
}

