#!/usr/bin/env node
/**
 * Winston 0.8 (via prompt → dendrynexus) reads target.padLevels during
 * circular init and triggers Node's padLevels export warning. Idempotent patch.
 */
const fs = require('fs');
const path = require('path');

const OLD =
  '  if (target.padLevels) {\n' +
  '    target.levelLength = exports.longestElement(Object.keys(target.levels));\n' +
  '  }';

const NEW =
  '  // Avoid reading padLevels on module.exports during winston circular init (Node warning).\n' +
  '  if (Object.prototype.hasOwnProperty.call(target, \'padLevels\') && target.padLevels) {\n' +
  '    target.levelLength = exports.longestElement(Object.keys(target.levels));\n' +
  '  }';

function findCommonFiles(dir, out) {
  if (!fs.existsSync(dir)) return;
  for (const name of fs.readdirSync(dir)) {
    const p = path.join(dir, name);
    let st;
    try {
      st = fs.statSync(p);
    } catch (_) {
      continue;
    }
    if (st.isDirectory()) {
      if (name === 'node_modules' || name === '.git') findCommonFiles(p, out);
      else if (p.endsWith(path.join('winston', 'lib', 'winston'))) {
        const common = path.join(p, 'common.js');
        if (fs.existsSync(common)) out.push(common);
      } else findCommonFiles(p, out);
    }
  }
}

const root = path.join(__dirname, '..', 'node_modules');
const files = [];
const direct = path.join(root, 'winston', 'lib', 'winston', 'common.js');
if (fs.existsSync(direct)) files.push(direct);
findCommonFiles(root, files);

const unique = [...new Set(files)];
if (!unique.length) {
  console.warn('patch-winston-padlevels: no winston common.js found (run npm install first)');
  process.exit(0);
}

let patched = 0;
for (const file of unique) {
  const src = fs.readFileSync(file, 'utf8');
  if (src.includes(NEW.trim().split('\n')[1])) {
    continue;
  }
  if (!src.includes(OLD)) {
    console.warn('patch-winston-padlevels: unexpected content in ' + file);
    continue;
  }
  fs.writeFileSync(file, src.replace(OLD, NEW));
  patched++;
  console.log('patch-winston-padlevels: patched ' + file);
}

if (!patched) {
  console.log('patch-winston-padlevels: already up to date');
}

