        const run = results.districts[d]
        if (!run) { continue }
        const seats = run.seats[d]
        for (const k of PARTY_KEYS) {
            Q['Proj_' + d + '_' + k] = seats[k]
        }
    }
}

function runElectionsAndWriteQ(opts) {
    opts = opts || {}
    if (typeof Q.applyElectorateModifiers === 'function') {
        Q.applyElectorateModifiers()
    }
    syncAllVoteAppeals(Q.stratums, electionState, Q.vote_labels, Q.global_shifts)
    const results = engine.runAll({
        month: opts.month != null ? opts.month : (Q.month || 1),
        allDistricts: opts.allDistricts !== false,
    })
    if (opts.commitSeats) {
        writeCommittedSeatsToQ(Q, results)
    }
    writeProjectionSeatsToQ(Q, results)
    writePollDisplaysToQ(Q, electionState, results)
    qified_pops(electionState)
    Q.electionResults = results
    return results
}

Q.stratumDisplay = STRATUM_DISPLAY
Q.districtDisplay = DISTRICT_DISPLAY

runElectionsAndWriteQ({ allDistricts: true, commitSeats: false })

Q.electionV2 = electionState
Q.electionEngine = engine
Q.electorate = engine
Q.voter_blocks = blocks
Q.qified_pops = function() { qified_pops(electionState) }
Q.update_projections = function(opts) {
    return runElectionsAndWriteQ(Object.assign({ commitSeats: false }, opts || {}))
}
Q.assignSeatsFromInitialPolling = function() {
    return runElectionsAndWriteQ({ month: 1, allDistricts: true, commitSeats: true })
}
engine.assign_seats = function(opts) {
    return runElectionsAndWriteQ(Object.assign({ commitSeats: true }, opts || {}))
}

