/** Popular-vote shares for status polls tab (executive-weighted). */
function writePollDisplaysToQ(Q, state, results) {
    const execPct = votesToPollPercents(results.executive.votes || zeroPartyVotes())
    for (const k of PARTY_KEYS) {
        Q['poll_exec_' + k] = execPct[k]
    }
    const byStratum = {}
    for (const sid of STRATUM_IDS) {
        byStratum[sid] = zeroPartyVotes()
    }
    const chamber = CHAMBERS.executive
    for (const block of state.blocks) {
        const { total } = tabulateBlock(
            block, state.interestGroups, chamber, state
        )
        const sid = block.demographic.id
        for (const k of PARTY_KEYS) {
            byStratum[sid][k] += total[k] || 0
        }
    }
    for (const sid of STRATUM_IDS) {
        const pct = votesToPollPercents(byStratum[sid] || zeroPartyVotes())
        for (const k of PARTY_KEYS) {
            Q[sid + '_poll_' + k] = pct[k]
        }
    }
    const byDistrict = {}
    for (const did of DISTRICT_IDS) {
        byDistrict[did] = zeroPartyVotes()
    }
    for (const block of state.blocks) {
        const { total } = tabulateBlock(
            block, state.interestGroups, chamber, state
        )
        const did = block.district.id
        for (const k of PARTY_KEYS) {
            byDistrict[did][k] += total[k] || 0
        }
    }
    for (const did of DISTRICT_IDS) {
        const pct = votesToPollPercents(byDistrict[did] || zeroPartyVotes())
        for (const k of PARTY_KEYS) {
            Q[did + '_poll_' + k] = pct[k]
        }
    }
}

