function writePollDisplaysToQ(Q, state, results) {
    const chamber = CHAMBERS.district
    const citywide = zeroPartyVotes()
    for (const did of DISTRICT_IDS) {
        const run = results.districts[did]
        if (run && run.byDistrict && run.byDistrict[did]) {
            for (const k of PARTY_KEYS) {
                citywide[k] += run.byDistrict[did][k] || 0
            }
        }
    }
    if (sum(PARTY_KEYS.map((k) => citywide[k])) === 0) {
