function tabulateBlock(block, interestGroups, chamber, state) {
    const ig = allocateIgVotes(block, state.interestGroups, chamber, state)
    const comp = allocateCompetitiveVotes(block, state.interestGroups, chamber, state)
    let result = {
        ig,
        comp,
        total: sumPartyVoteObjects(ig, comp),
    }
    result = applyBlockVoteRules(block, result, state, chamber)
    const weight = chamber.useExecutiveWeight ? block.demographic.executiveWeight : 1
    if (weight !== 1) {
        for (const k of PARTY_KEYS) {
            result.total[k] *= weight
        }
    }
    return result
}

input.new_string:
function tabulateBlock(block, interestGroups, chamber, state) {
    const t = tabulateBlockWithAbstention(block, interestGroups, chamber, state)
    return { ig: t.ig, comp: t.comp, total: t.total }
}

/** Pre/post rule ballot mass (for corp-or-abstain drone blocks). */
function tabulateBlockWithAbstention(block, interestGroups, chamber, state) {
    const ig = allocateIgVotes(block, interestGroups, chamber, state)
    const comp = allocateCompetitiveVotes(block, interestGroups, chamber, state)
    const preRule = sumPartyVoteObjects(ig, comp)
    let result = {
        ig,
        comp,
        total: preRule,
    }
    result = applyBlockVoteRules(block, result, state, chamber)
    const weight = chamber.useExecutiveWeight ? block.demographic.executiveWeight : 1
    let ballotMass = sum(PARTY_KEYS.map((k) => preRule[k] || 0))
    let countedMass = sum(PARTY_KEYS.map((k) => result.total[k] || 0))
    if (weight !== 1) {
        ballotMass *= weight
        for (const k of PARTY_KEYS) {
            result.total[k] = (result.total[k] || 0) * weight
        }
        countedMass = sum(PARTY_KEYS.map((k) => result.total[k] || 0))
    }
    return {
        ig: result.ig,
        comp: result.comp,
        total: result.total,
        ballotMass,
        countedMass,
        abstentionMass: Math.max(0, ballotMass - countedMass),
    }
}

